INSERT INTO `goals` (`goal_id`, `user_id`, `name`, `description`, `created_at`, `updated_at`, `created_by`, `year`, `quarter`, `employee_id`, `weight`, `pillar_id`, `start_year`, `end_year`, `is_active`) VALUES
  (225, 80, 'ግብ 1 .  ዓለም አቀፍ ደረጃውን የጠበቀ እና ዘመናዊ መሰረተ ልማት ማልማት', 'SG1\tDevelop world class and smart physical infrastructure   ', '2026-07-15 11:30:45', '2026-09-01 12:08:16', NULL, 2019, '1', 153, '7.5000', 1, 2018, 2024, 1),
  (226, 40, 'ግብ 2. አይበገሬ(ጠንካራ) የዲጅታል መሰረተ ልማት እና ፕላትፎርሞችን መገንባት', 'አይበገሬ(ጠንካራ) የዲጅታል መሰረተ ልማት እና ፕላትፎርሞችን መገንባት', '2026-07-19 17:46:38', '2026-08-20 09:52:32', NULL, 2019, '1', 109, '9.0000', 1, 2018, 2024, 1),
  (227, 80, 'ግብ 3\tበኤአይ(AI) የተደገፈ ሀገር በቀል ስማርት የማኑፋክቸሪንግ ኢኮሲስተም መገንባት', 'SG3\tBuild AI-enabled smart manufacturing ecosystem to accelerate indigenous high-tech production', '2026-07-21 07:22:43', '2026-09-01 12:47:40', NULL, 2019, '1', 153, '6.0000', 1, 2018, 2024, 1),
  (228, 80, 'ግብ 4 \tየፓርኩን ተወዳዳሪነትና ገፅታን በማጠናከር ኢንቨስትመንትን መሳብ', 'Attract investment through improved competitiveness and visibility', '2026-07-21 07:37:15', '2026-08-20 09:53:14', NULL, 2019, '1', 153, '12.0000', NULL, 2018, 2024, 1),
  (229, 80, 'ግብ 5\tበኤአይ(AI) የተደገፈ ምርምር፣ ፈጠራ እና ቴክኖሎጂን ወደ ገበያ ማውጣትን ማሳደግ።', 'Advance AI-enabled research, Innovation, and technology commercialization', '2026-07-21 07:50:32', '2026-08-20 09:53:43', NULL, 2019, '1', 153, '7.0000', NULL, 2018, 2024, 1),
  (230, 80, 'ግብ 6\tየዲጂታል ታለንት ስርዓትን መገንባት እና ኢንተርፕሪነርሺፕ፣ ኢንኩቤሽን እና ስታርታፕ እድገትን ማፋጠን', 'SG6\tBuild digital talent pipeline and accelerate entrepreneurship, incubation, and startup growth', '2026-07-21 07:52:17', '2026-09-01 13:33:14', NULL, 2019, '1', 153, '8.0000', NULL, 2018, 2024, 1),
  (231, 80, 'ግብ 7 \tየሥራ ፈጠራን ማሳደግ፣ ዲጂታል ዕድሎችን ማስፋፋት፣ አገር በቀል ቴክኖሎጂዎችን ማበልፀግ እና የወጪ ንግድ አፈጻጸምን ማጠናከር።', 'SG7\tAccelerate employment, digital opportunity,  and exports', '2026-07-21 07:54:10', '2026-08-20 09:56:34', NULL, 2019, '1', 153, '18.0000', NULL, 2018, 2024, 1),
  (232, 80, 'ግብ 8\tየፓርኩን መሠረተ ልማት፣ ኮምፓውንድ እና  ማኅበረሰብ ለመጠበቅ ስማርት ቴክኖሎጂን መጠቀም።', 'Leverage smart technology to secure the park infrastructure, compound and community. ', '2026-07-21 07:58:25', '2026-08-20 09:56:56', NULL, 2019, '1', 153, '9.0000', NULL, 2018, 2024, 1),
  (233, 80, 'ግብ 9\tየኮርፖሬት አገልግሎቶችን ዲጂታላይዝ ማድረግ እና የሕግና ፖሊሲ ማዕቀፎችን ማጠናከር።', 'Digitalize corporate services and strengthen legal and policy frameworks', '2026-07-21 08:03:51', '2026-08-21 08:38:06', NULL, 2019, '1', 153, '10.0000', 3, 2018, 2024, 1),
  (234, 80, 'ግብ 10.\tየሰው ሀብት  አስተዳደር፣ ተቋማዊ አቅም ግንባታ ፤ሀብት አጠቃቀምን እና የገቢ እድገትን ማረጋገጥ (70%)', 'Ensure workforce performance, resource optimization, and revenue growth.', '2026-07-21 08:04:54', '2026-08-21 12:09:59', NULL, 2019, '1', 153, '10.0000', 3, 2018, 2024, 1);
