INSERT INTO `objectives` (`objective_id`, `user_id`, `name`, `description`, `created_at`, `updated_at`, `created_by`, `year`, `quarter`, `employee_id`, `goal_id`, `weight`) VALUES
  (270, 80, 'ዓላማ 1.1 \tአስተማማኝ የፋሲሊቲ ኦፕሬሽንስ እና የአገልግሎት አቅርቦትን ማረጋገጥ', 'አስተማማኝ የፋሲሊቲ ኦፕሬሽንስ እና የአገልግሎት አቅርቦትን ማረጋገጥ', '2026-07-15 11:33:12', '2026-09-01 12:08:42', NULL, NULL, NULL, 153, 225, '2.5000'),
  (271, 40, 'ዓላማ 2.1 ኤአይን(AI) መሰረት ያደረገ የዲጅታል መሰረተ ልማት መገንባት', ' ኤአይን(AI) መሰረት ያደረገ የዲጅታል መሰረተ ልማት መገንባት', '2026-07-19 17:48:09', '2026-09-01 12:36:36', NULL, NULL, NULL, 109, 226, '3.0000'),
  (273, 80, 'ዓላማ 4.1\tየዓለም አቀፍ ገበያ ተደራሽነትን ለማሻሻል በዲጂታል ቴክኖሎጂ ዘርፍ የውጭ ቀጥተኛ ኢንቨስትመንትን መሳብ።', 'የዓለም አቀፍ ገበያ ተደራሽነትን ለማሻሻል በዲጂታል ቴክኖሎጂ ዘርፍ የውጭ ቀጥተኛ ኢንቨስትመንትን መሳብ።', '2026-07-21 07:39:53', '2026-09-01 12:54:55', NULL, NULL, NULL, 153, 228, '4.0000'),
  (280, 80, 'ዓላማ 1.2 \tየቅድመ-መከላከል እና የትንበያ ጥገና አሰራርን ማጠናከር', 'የቅድመ-መከላከል እና የትንበያ ጥገና አሰራርን ማጠናከር', '2026-07-22 11:11:16', '2026-09-01 12:09:13', NULL, NULL, NULL, 153, 225, '1.0000'),
  (284, 80, 'ዓላማ 1.3 \tየአካባቢ ዘላቂነትን ማረጋገጥ እና የሃብት አጠቃቀም ብቃትን ማሻሻል', 'የአካባቢ ዘላቂነትን ማረጋገጥ እና የሃብት አጠቃቀም ብቃትን ማሻሻል', '2026-07-22 11:14:10', '2026-09-01 12:13:53', NULL, NULL, NULL, 153, 225, '0.5000'),
  (291, 80, 'ዓላማ 1.4 \tየጤና፣ የሥራ ላይ ደህንነት  ፣ የንብረት ጥበቃና ደህንነት ቁጥጥር እና የህግ ተገዢነት አሰራርን ማጠናከር', 'የጤና፣ የሥራ ላይ ደህንነት  ፣ የንብረት ጥበቃና ደህንነት ቁጥጥር እና የህግ ተገዢነት አሰራርን ማጠናከር', '2026-07-22 12:01:40', '2026-09-01 12:14:11', NULL, NULL, NULL, 153, 225, '0.5000'),
  (296, 80, 'ዓላማ 1.5 \tየማስተር ፕላን አተገባበር እና የልማት ቁጥጥር ሥርዓትን ማጠናከር።', 'የማስተር ፕላን አተገባበር እና የልማት ቁጥጥር ሥርዓትን ማጠናከር።', '2026-07-22 12:07:47', '2026-09-01 12:21:14', NULL, NULL, NULL, 153, 225, '3.0000'),
  (313, 80, 'ዓላማ 2.2\tሀገር በቀል የዲጅታል ፕላትፎርሞችን እና መፍትሄዎችን ማልማት', 'ሀገር በቀል የዲጅታል ፕላትፎርሞችን እና መፍትሄዎችን ማልማት', '2026-07-22 12:45:12', '2026-09-01 12:36:52', NULL, NULL, NULL, 153, 226, '4.0000'),
  (320, 80, 'ዓላማ 2.3\tየሳይበር ደህንነት፣ የዳታ ጥበቃ እና የዲጂታል አስተዳደር ማዕቀፎችን ማጠናከር', 'የሳይበር ደህንነት፣ የዳታ ጥበቃ እና የዲጂታል አስተዳደር ማዕቀፎችን ማጠናከር', '2026-07-22 13:04:00', '2026-09-01 12:37:13', NULL, NULL, NULL, 153, 226, '2.0000'),
  (324, 80, 'ዓላማ 3.1\tየሃገር ውስጥ አምራች ተቋማት ምርታቸውን በኤአይ የታገዘ እንዲሆን እገዛ እና ክትትል ማድረግ', 'የሃገር ውስጥ አምራች ተቋማት ምርታቸውን በኤአይ የታገዘ እንዲሆን እገዛ እና ክትትል ማድረግ', '2026-07-27 09:13:18', '2026-09-01 12:51:24', NULL, NULL, NULL, 153, 227, '2.5000'),
  (326, 80, 'ዓላማ 3.2\tበሰው ሰራሽ አስተውህሎት (AI) የተደገፈ ስማርት የማኑፋክቸሪንግ እና የገበያ ማስፋፊያ ስራዎችን ማሳደግ', 'በሰው ሰራሽ አስተውህሎት (AI) የተደገፈ ስማርት የማኑፋክቸሪንግ እና የገበያ ማስፋፊያ ስራዎችን ማሳደግ', '2026-07-27 09:14:37', '2026-09-01 12:51:07', NULL, NULL, NULL, 153, 227, '2.0000'),
  (331, 80, 'ዓላማ 4.2\tየፓርኩን ነዋሪ ኩባንያዎች ቆይታ ማጠናከርና ለኢንቨስተሮች የድህረ ኢንቨስትመንት ድጋፍ እና ክትትል አገልግሎቶችን ማሻሻል', 'የፓርኩን ነዋሪ ኩባንያዎች ቆይታ ማጠናከርና ለኢንቨስተሮች የድህረ ኢንቨስትመንት ድጋፍ እና ክትትል አገልግሎቶችን ማሻሻል', '2026-07-27 09:18:20', '2026-09-01 12:55:07', NULL, NULL, NULL, 153, 228, '2.0000'),
  (333, 80, 'ዓላማ 4.3\tየፓርኩን የንግድ ልማት፣ የገበያ ትስስር እና ስልታዊ ሽርክናዎችን  ማስፋፋት', 'የፓርኩን የንግድ ልማት፣ የገበያ ትስስር እና ስልታዊ ሽርክናዎችን  ማስፋፋት', '2026-07-27 09:19:18', '2026-09-01 12:55:22', NULL, NULL, NULL, 153, 228, '3.0000'),
  (336, 80, 'ዓላማ 4.4\tፓርኩን በሀገር አቀፍና በዓለም አቀፍ ደረጃ ተወዳዳሪ እና ተዓማኒ ብራንድ አድርጎ መገንባት', 'ፓርኩን በሀገር አቀፍና በዓለም አቀፍ ደረጃ ተወዳዳሪ እና ተዓማኒ ብራንድ አድርጎ መገንባት', '2026-07-27 09:21:05', '2026-09-01 12:55:47', NULL, NULL, NULL, 153, 228, '3.0000'),
  (341, 80, 'ዓላማ 5.1\tከዩኒቨርሲቲዎች፣ ከምርምር ተቋማት፣ ከኢንዱስትሪዎች እና ከዓለም አቀፍ የፈጠራ አጋሮች ጋር ትብብርን ማጠናከር', 'ከዩኒቨርሲቲዎች፣ ከምርምር ተቋማት፣ ከኢንዱስትሪዎች እና ከዓለም አቀፍ የፈጠራ አጋሮች ጋር ትብብርን ማጠናከር', '2026-07-27 09:40:06', '2026-09-01 13:16:09', NULL, NULL, NULL, 153, 229, '3.0000'),
  (344, 80, 'ዓላማ 5.2\tኤአይ(AI) መሰረት ያደረገ የምርምር፣ ፕሮቶታይፖች እና የፈጠራ መፍትሄዎችን ማልማት', 'ኤአይ(AI) መሰረት ያደረገ የምርምር፣ ፕሮቶታይፖች እና የፈጠራ መፍትሄዎችን ማልማት', '2026-07-27 09:41:53', '2026-09-01 13:16:23', NULL, NULL, NULL, 153, 229, '3.0000'),
  (348, 80, 'ዓላማ 5.3\tዘመናዊ የኤአይ፣ የሮቦቲክስ እና አዳዲስ ቴክኖሎጂ ላቦራቶሪዎችና የፈጠራ ሙከራ ማዕከላትን ማቋቋም', 'ዘመናዊ የኤአይ፣ የሮቦቲክስ እና አዳዲስ ቴክኖሎጂ ላቦራቶሪዎችና የፈጠራ ሙከራ ማዕከላትን ማቋቋም', '2026-07-27 09:45:39', '2026-09-01 13:16:40', NULL, NULL, NULL, 153, 229, '1.0000'),
  (357, 80, 'ዓላማ 7.1\tበአርቴፊሻል ኢንተለጀንስ (AI)፣ በኢንፎርሜሽንና ኮሙኒኬሽን ቴክኖሎጂ (ICT)፣ በጀማሪ ድርጅቶች (Startups)፣ የንግድ ሂደት ስራዎችን ለውጭ ሀገራት አቅርቦት (BPO) እና በዲጂታል የማምረት አገልግሎቶች (manufacturing) በኩል የሥራ ዕድሎችን መፍጠር።', '\nበአርቴፊሻል ኢንተለጀንስ (AI)፣ በኢንፎርሜሽንና ኮሙኒኬሽን ቴክኖሎጂ (ICT)፣ በጀማሪ ድርጅቶች (Startups)፣ የንግድ ሂደት ስራዎችን ለውጭ ሀገራት አቅርቦት (BPO) እና በዲጂታል የማምረት አገልግሎቶች (manufacturing) በኩል የሥራ ዕድሎችን መፍጠር።', '2026-08-04 12:09:09', '2026-09-02 09:17:30', NULL, NULL, NULL, 153, 231, '9.0000'),
  (360, 80, 'ዓላማ 8.1\t\"የፓርኩ ማህበረሰብ በፓርኩ ላይ ያላቸውን ተዓማኒነት  እና ደህንነትን መገንባት\"', '\"የፓርኩ ማህበረሰብ በፓርኩ ላይ ያላቸውን ተዓማኒነት  እና ደህንነትን መገንባት\"', '2026-08-04 12:11:26', '2026-09-02 09:19:20', NULL, NULL, NULL, 153, 232, '3.0000'),
  (362, 80, 'ዓላማ 8.2\tየፓርኩን መግቢያ በሮች ፤  ልዩ ልዩ ሀብቶች እና መሰረተ ልማቶች  መቆጣጠር', 'የፓርኩን መግቢያ በሮች ፤  ልዩ ልዩ ሀብቶች እና መሰረተ ልማቶች  መቆጣጠር', '2026-08-04 12:12:37', '2026-09-02 09:19:36', NULL, NULL, NULL, 153, 232, '4.0000'),
  (370, 80, 'ዓላማ 8.3\t\"የጥበቃ ስርዓቱን በስማርት ቴክኖሎጂ  ማጠናከር\"', '\"የጥበቃ ስርዓቱን በስማርት ቴክኖሎጂ  ማጠናከር\"', '2026-08-04 12:32:16', '2026-09-02 09:19:48', NULL, NULL, NULL, 153, 232, '2.0000'),
  (373, 80, 'ዓላማ 9.1\tየተቀም ስጋቶችን ለማስተዳደር ደረጃውን የጠበቀ የኦዲት ስርዓት መዘርጋት', 'የተቀም ስጋቶችን ለማስተዳደር ደረጃውን የጠበቀ የኦዲት ስርዓት መዘርጋት', '2026-08-04 12:39:50', '2026-09-02 09:21:17', NULL, NULL, NULL, 153, 233, '4.0000'),
  (391, 80, 'ዓላማ 10.1\tየሠራተኞችን ክህሎትና የአመራር አቅምን ማሳደግ(10%)', 'የሠራተኞችን ክህሎትና የአመራር አቅምን ማሳደግ(10%)', '2026-08-04 13:36:47', '2026-09-01 14:06:57', NULL, NULL, NULL, 153, 234, '0.0000'),
  (395, 80, 'ዓላማ 10.2\tክፍት የሆኑ የስራ መደቦችን እንደአስፈላጊነቱ የሰው ኃይል ማሟለት (10%)', 'ክፍት የሆኑ የስራ መደቦችን እንደአስፈላጊነቱ የሰው ኃይል ማሟለት (10%)', '2026-08-04 14:11:41', '2026-09-01 14:07:05', NULL, NULL, NULL, 153, 234, '0.0000'),
  (398, 80, 'ዓላማ 10.3\tየኮርፖሬሽኑን  ሀብት እና ንብረት አስተዳደር ስረዓት ማሳደግ (10%)', 'የኮርፖሬሽኑን  ሀብት እና ንብረት አስተዳደር ስረዓት ማሳደግ (10%)', '2026-08-04 14:13:31', '2026-09-01 14:07:02', NULL, NULL, NULL, 153, 234, '0.0000'),
  (402, 80, 'ዓላማ 10.4\tለኮርፖሬሽኑ መሰረታዊ አገልግሎች መስጠት (10%)', 'ለኮርፖሬሽኑ መሰረታዊ አገልግሎች መስጠት (10%)', '2026-08-04 14:35:10', '2026-09-08 15:46:47', NULL, NULL, NULL, 153, 234, NULL),
  (405, 80, 'ዓላማ 10.5\tገቢ አሰባሰብን  ማሻሻልና ወጪን ዉጤታማ  በሆነ ሁኔታ ማስተዳደር (20%)', 'ገቢ አሰባሰብን  ማሻሻልና ወጪን ዉጤታማ  በሆነ ሁኔታ ማስተዳደር (20%)\n', '2026-08-04 14:37:01', '2026-09-08 15:46:55', NULL, NULL, NULL, 153, 234, NULL),
  (408, 80, 'ዓላማ 3.3\tለAI እና ለላቀ ማኑፋክቸሪንግ ልዩ የፈጠራ ዞኖችን ማልማት', 'ለAI እና ለላቀ ማኑፋክቸሪንግ ልዩ የፈጠራ ዞኖችን ማልማት', '2026-08-06 09:04:53', '2026-09-01 12:50:54', NULL, NULL, NULL, 153, 227, '1.5000'),
  (409, 80, 'ዓላማ 6.1\tየዲጂታል ታለንት ስርዓትን ማልማትና ማጠናከር', '\tየዲጂታል ታለንት ስርዓትን ማልማትና ማጠናከር', '2026-08-07 08:05:12', '2026-09-01 14:55:08', NULL, NULL, NULL, 153, 230, '2.0000'),
  (410, 80, 'ዓላማ 6.2 \tየኢንኩቤሽን ማዕከላትን ማቋቋም እና የስታርታፕ እድገትን ማፋጠን', 'የኢንኩቤሽን ማዕከላትን ማቋቋም እና የስታርታፕ እድገትን ማፋጠን', '2026-08-07 08:05:45', '2026-09-01 14:55:29', NULL, NULL, NULL, 153, 230, '4.0000'),
  (411, 80, 'ዓላማ 6.3\tለጀማሪ ስራ ፈጣሪዎች የገንዘብ ድጋፍ እንዲያገኙ ማመቻቸት ', 'ለጀማሪ ስራ ፈጣሪዎች የገንዘብ ድጋፍ እንዲያገኙ ማመቻቸት ', '2026-08-07 08:06:12', '2026-09-01 14:55:47', NULL, NULL, NULL, 153, 230, '2.0000'),
  (412, 80, 'ዓላማ 7.2\tየፓርኩ ነዋሪ ኩባንያዎች አገር በቀል የቴክኖሎጂ መፍትሔዎችን እንዲያለሙና እንዲያስፋፉ ማበረታታት', 'የፓርኩ ነዋሪ ኩባንያዎች አገር በቀል የቴክኖሎጂ መፍትሔዎችን እንዲያለሙና እንዲያስፋፉ ማበረታታት', '2026-08-07 08:40:42', '2026-09-03 13:26:03', NULL, NULL, NULL, 153, 231, '9.0000'),
  (413, 80, 'ዓላማ 10.6\tዉጤታማ  የኮርፖሬት ግዥ ማረጋገጥ (10%)', 'ዉጤታማ  የኮርፖሬት ግዥ ማረጋገጥ (10%)', '2026-08-07 09:09:18', '2026-09-01 14:07:24', NULL, NULL, NULL, 153, 234, '0.0000'),
  (416, 80, 'ዓላማ 9.2\tየሕግና ፖሊሲ ማዕቀፎችን በማጠናከር የአሰራር ሂደትን ደረጃውን የጠበቀ ማድረግ', 'የሕግና ፖሊሲ ማዕቀፎችን በማጠናከር የአሰራር ሂደትን ደረጃውን የጠበቀ ማድረግ', '2026-08-20 12:52:01', '2026-09-02 09:21:33', NULL, NULL, NULL, 153, 233, '5.0000'),
  (418, 40, ' ዓላማ 9.3 ዲጂታላይዜሽን (15%)', 'ዲጂታላይዜሽን (15%)', '2026-08-21 12:13:01', '2026-09-02 09:21:41', NULL, NULL, NULL, 109, 233, '1.0000');
