  `assigned_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_monthly_assignee` (`monthly_task_id`,`user_id`),
  CONSTRAINT `monthly_task_assignees_ibfk_1` FOREIGN KEY (`monthly_task_id`) REFERENCES `monthly_tasks` (`monthly_task_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- ----------------------------------------------------------------------------
-- Table structure & data for table `monthly_tasks`
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `monthly_tasks`;
CREATE TABLE `monthly_tasks` (
  `monthly_task_id` int(11) NOT NULL AUTO_INCREMENT,
  `specific_objective_detail_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `weight` decimal(5,2) NOT NULL DEFAULT 0.00,
  `plan_amount` decimal(15,2) DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `progress` decimal(5,2) NOT NULL DEFAULT 0.00,
  `plan_progress` decimal(5,2) DEFAULT 0.00,
  `status` enum('Pending','In Progress','Confirmed') NOT NULL DEFAULT 'Confirmed',
  `description` text DEFAULT NULL,
  `attachment` varchar(255) DEFAULT NULL,
  `actual_amount` decimal(15,4) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `deadline` date DEFAULT NULL,
  `wbr_group` varchar(100) NOT NULL DEFAULT 'WBR1',
  `wbr_group_weight` decimal(5,2) NOT NULL DEFAULT 0.00,
  `wbr_group_plan_amount` decimal(15,4) NOT NULL DEFAULT 0.0000,
  PRIMARY KEY (`monthly_task_id`),
  KEY `idx_specific_objective_detail` (`specific_objective_detail_id`),
  KEY `idx_monthly_task_weight` (`weight`),
  CONSTRAINT `fk_monthly_task_detail` FOREIGN KEY (`specific_objective_detail_id`) REFERENCES `specific_objective_details` (`specific_objective_detail_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- ----------------------------------------------------------------------------
-- Table structure & data for table `notifications`
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `notification_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `plan_id` int(11) DEFAULT NULL,
  `type` enum('comment','reply','status_change','deadline_alert','plan_update','meeting','task','message') NOT NULL,
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `is_read` tinyint(1) DEFAULT 0,
  `priority` enum('low','medium','high','urgent') DEFAULT 'medium',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `read_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`notification_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_plan_id` (`plan_id`),
  KEY `idx_type` (`type`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_priority` (`priority`),
  KEY `idx_user_unread` (`user_id`,`is_read`),
  KEY `idx_user_type` (`user_id`,`type`),
  KEY `idx_plan_user` (`plan_id`,`user_id`),
  CONSTRAINT `notifications_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `notifications_ibfk_2` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`plan_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=690 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


