  CONSTRAINT `plan_approval_steps_ibfk_2` FOREIGN KEY (`org_node_id`) REFERENCES `organization_structure` (`id`),
  CONSTRAINT `plan_approval_steps_ibfk_3` FOREIGN KEY (`approver_employee_id`) REFERENCES `employees` (`employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=876 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- ----------------------------------------------------------------------------
